import sys

def solve(s):
    s = list(s)
    n = len(s)
    for i in range(n):
        if s[i] == '?':
            s[i] = 'A'
    for i in range(n - 3):
        if s[i] == 'C' or s[i] == '?':
            if s[i + 1] == 'H' or s[i + 1] == '?':
                if s[i + 2] == 'E' or s[i + 2] == '?':
                    if s[i + 3] == 'F' or s[i + 3] == '?':
                        if s[i] == '?':
                            s[i] = 'C'
                        if s[i + 1] == '?':
                            s[i + 1] = 'H'
                        if s[i + 2] == '?':
                            s[i + 2] = 'E'
                        if s[i + 3] == '?':
                            s[i + 3] = 'F'
    return ''.join(s)

input = sys.stdin.read().splitlines()
t = int(input[0])
test_cases = input[1:]
outputs = [solve(s) for s in test_cases]
for output in outputs:
    print(output)
